    const im = imgCache.get(n); if (!im) continue;
    const w = im.naturalWidth || im.width, h = im.naturalHeight || im.height;
    const c = mk(w, h), g = c.getContext('2d'); g.drawImage(im, 0, 0);
    const d = g.getImageData(0, 0, w, h).data;
